# ==============================================================
# Prokaryotic annotation: 6-state scheme (CDS only, no introns).
# Parallel to Tiberius annotation_gtf; for RefSeq-style GFF3.
# ==============================================================
#
# State scheme:
#   0 = Intergenic
#   1 = Coding frame 0
#   2 = Coding frame 1
#   3 = Coding frame 2
#   4 = START codon region (see boundary mode below)
#   5 = STOP codon region (see boundary mode below)
# ==============================================================

import os
import numpy as np
from collections import defaultdict
from typing import List, Optional

NUM_STATES = 6

# v4: merged genomic position, multi-label (sigmoid/BCE). Multiple classes may be 1.
# 0=IGR (neither strand coding at this base), 1–3=Frame0/1/2 on + strand, 4–6=Frame0/1/2 on − strand,
# 7=START (+), 8=START (−), 9=STOP (+), 10=STOP (−). Overlapping CDSs are
# accumulated transcript-by-transcript, so same-strand CDS+START and
# opposite-strand signals can coexist at one genomic base.
NUM_STATES_V4 = 11

# v4 smorf-split: small vs long ORF frames, universal strand-specific START/STOP.
# 0=IGR, 1–3=small f0/f1/f2 (+), 4–6=small f0/f1/f2 (−),
# 7–9=long f0/f1/f2 (+), 10–12=long f0/f1/f2 (−),
# 13=START (+), 14=START (−), 15=STOP (+), 16=STOP (−).
NUM_STATES_V4_SMORF_SPLIT = 17
V4_SPLIT_CH_START_PLUS, V4_SPLIT_CH_START_MINUS = 13, 14
V4_SPLIT_CH_STOP_PLUS, V4_SPLIT_CH_STOP_MINUS = 15, 16
V4_SPLIT_F1_CLASSES_DEFAULT = tuple(range(1, NUM_STATES_V4_SMORF_SPLIT))

# How START/STOP are painted onto bases for class labels 4 and 5:
#   "triple" (default) — all 3 bases of the start/stop codon are labeled.
#   "edge"           — only the first base of START and the last base of STOP
#                      (translation-direction) receive labels 4 / 5.
_BOUNDARY_MODE = os.environ.get("PROK_BOUNDARY_LABEL_MODE", "triple").strip().lower()
if _BOUNDARY_MODE not in {"triple", "edge"}:
    raise ValueError(
        "PROK_BOUNDARY_LABEL_MODE must be 'triple' or 'edge', "
        f"got {_BOUNDARY_MODE!r}",
    )


def set_boundary_label_mode(mode: str) -> None:
    """Switch global START/STOP labeling style ('triple' or 'edge').

    Prefer setting ``PROK_BOUNDARY_LABEL_MODE`` before importing this module;
    this setter exists for notebooks/tests.
    """
    global _BOUNDARY_MODE
    m = mode.strip().lower()
    if m not in {"triple", "edge"}:
        raise ValueError(f"mode must be 'triple' or 'edge', got {mode!r}")
    _BOUNDARY_MODE = m


def get_boundary_label_mode() -> str:
    return _BOUNDARY_MODE


def _parse_gene_group_id(attributes: str) -> Optional[str]:
    """Stable gene/locus key for collapsing isoforms (Tiberius: longest CDS per gene). RefSeq GFF3 order."""
    for tag in ("gene=", "Gene=", "locus_tag=", "Locus_tag=", "old_locus_tag="):
        if tag in attributes:
            try:
                v = attributes.split(tag, 1)[1].split(";")[0].strip().strip('"')
                if v:
                    return v
            except IndexError:
                pass
    if "Parent=" in attributes:
        return attributes.split("Parent=")[1].split(";")[0].strip()
    return None


def _normalize_seqid(seqid_str: str) -> str:
    """First token only (match FASTA header parsing)."""
    return seqid_str.strip().split()[0]


def _normalize_phase(phase) -> int:
    """Convert GFF/GTF phase to int; '.' or missing -> 0."""
    if phase is None or phase == "" or phase == ".":
        return 0
    return int(phase)


class GeneFeature:
    """A single CDS segment (prokaryotic: no introns)."""

    def __init__(
        self,
        feature_type: str,
        start: int,
        end: int,
        strand: str,
        phase,
    ) -> None:
        self.type = feature_type
        self.start = start
        self.end = end
        self.strand = strand
        self.phase = _normalize_phase(phase)

    def to_class_labels(self) -> np.ndarray:
        """Per-base labels in [1..5] for this segment. 1/2/3 = frame, 4 = START, 5 = STOP."""
        length = self.end - self.start + 1
        offset = (3 - self.phase) % 3
        labels = (np.arange(length, dtype=np.int32) + offset) % 3 + 1
        edge = get_boundary_label_mode() == "edge"
        if self.strand == "+":
            if edge:
                labels[0] = 4
                if length > 3:
                    labels[length - 1] = 5
            else:
                labels[:min(3, length)] = 4                          # START at 5' end
                if length > 3:
                    labels[max(length - 3, 3):] = 5                  # STOP at 3' end (no overlap w/ START)
        else:
            # Before reversal: high genomic pos = 5' (START), low = 3' (STOP)
            if edge:
                labels[length - 1] = 4
                if length > 3:
                    labels[0] = 5
            else:
                labels[max(length - 3, 0):] = 4                      # START
                if length > 3:
                    labels[:min(3, length - 3)] = 5                   # STOP
            labels = labels[::-1]
        return labels

    def to_one_hot(self) -> np.ndarray:
        """One-hot of shape (length, 5)."""
        labels = self.to_class_labels()
        return np.eye(NUM_STATES, dtype=np.int32)[labels]


class Transcript:
    """One transcript: one or more CDS segments (no introns)."""

    def __init__(self, tx_id: str) -> None:
        self.id = tx_id
        self.gene_group_id: Optional[str] = None
        self.sequence_name: Optional[str] = None
        self.strand: Optional[str] = None
        self.features: List[GeneFeature] = []
        self.start: Optional[int] = None
        self.end: Optional[int] = None

    def read_input(self, lines: List[str]) -> None:
        """Parse GTF/GFF lines for this transcript; CDS only, no intron inference."""
        for line in lines:
            parts = line.strip().split("\t")
            if len(parts) < 9:
                continue
            (
                chromosome,
                source,
                feature,
                start,
                end,
                score,
                strand,
                phase,
                attributes,
            ) = parts[:9]
            if feature != "CDS":
                continue
            if self.gene_group_id is None:
                gid = _parse_gene_group_id(attributes)
                self.gene_group_id = gid if gid else self.id
            seqid = _normalize_seqid(chromosome)
            if self.sequence_name and self.sequence_name != seqid:
                raise ValueError(
                    f"Transcript {self.id} spans multiple chromosomes: "
                    f"{self.sequence_name} and {seqid}"
                )
            self.sequence_name = seqid
            if self.strand and self.strand != strand:
                raise ValueError(
                    f"Transcript {self.id} has inconsistent strand: "
                    f"{self.strand} and {strand}"
                )
            self.strand = strand
            self.features.append(
                GeneFeature(
                    feature_type="CDS",
                    start=int(start),
                    end=int(end),
                    strand=strand,
                    phase=phase,
                )
            )

        self.features.sort(key=lambda x: x.start)
        if self.features:
            self.start = min(f.start for f in self.features)
            self.end = max(f.end for f in self.features)

        # Recalculate phases along CDS (handles multi-segment/frameshift)
        indices = (
            range(len(self.features))
            if self.strand == "+"
            else range(len(self.features) - 1, -1, -1)
        )
        running_phase = 0
        for i in indices:
            feat = self.features[i]
            feat.phase = running_phase
            seg_len = feat.end - feat.start + 1
            running_phase = (3 - (seg_len - running_phase) % 3) % 3

    def to_class_labels(self) -> np.ndarray:
        """Full transcript label vector; 0 = intergenic, 1–3 = frames, 4 = START, 5 = STOP."""
        length = self.end - self.start + 1
        labels = np.zeros(length, dtype=np.int32)
        for feat in self.features:
            rel_start = feat.start - self.start
            rel_end = feat.end - self.start
            labels[rel_start : rel_end + 1] = feat.to_class_labels()
        return labels

    def to_one_hot(self) -> np.ndarray:
        """One-hot of shape (L, 5)."""
        labels = self.to_class_labels()
        return np.eye(NUM_STATES, dtype=np.int32)[labels]


class Annotation:
    """GTF/GFF annotation (6-state labels). In-memory; use get_full_chromosome_labels for PyTorch Dataset windowing."""

    def __init__(
        self,
        file_path: str,
        seqnames: List[str],
        seq_lens: List[int],
    ) -> None:
        self.file_path = file_path
        self.seqnames = seqnames
        self.seq_lens = seq_lens
        self.transcripts: List[Transcript] = []

    def _parse_transcript_id(self, attributes: str) -> Optional[str]:
        """Extract transcript (or gene) ID from GTF/GFF3 attributes.
        Prefer Parent over ID so that CDS with the same Parent (gene/mRNA) group as one transcript.
        """
        if "transcript_id" in attributes:
            try:
                return attributes.split('transcript_id "')[1].split('"')[0]
            except IndexError:
                pass
        if "Parent=" in attributes:
            return attributes.split("Parent=")[1].split(";")[0].strip()
        if "ID=" in attributes:
            return attributes.split("ID=")[1].split(";")[0].strip()
        return None

    def read_inputfile(self) -> None:
        """Read GTF/GFF and build Transcript objects; CDS only."""
        transcript_lines: dict = {}
        with open(self.file_path, "r") as f:
            for line in f:
                if line.startswith("#") or line.startswith("track"):
                    continue
                parts = line.strip().split("\t")
                if len(parts) < 9:
                    continue
                (
                    chromosome,
                    source,
                    feature,
                    start,
                    end,
                    score,
                    strand,
                    phase,
                    attributes,
                ) = parts[:9]
                seqid = _normalize_seqid(chromosome)
                if seqid not in self.seqnames:
                    continue
                if feature != "CDS":
                    continue
                transcript_id = self._parse_transcript_id(attributes)
                if transcript_id is None:
                    raise ValueError(
                        f"Transcript ID not found in line: {line.strip()}"
                    )
                if transcript_id not in transcript_lines:
                    transcript_lines[transcript_id] = []
                transcript_lines[transcript_id].append(line.strip())

        for tx_id, tx_lines in transcript_lines.items():
            self.transcripts.append(Transcript(tx_id))
            self.transcripts[-1].read_input(tx_lines)

    def keep_longest_cds_per_gene(self) -> None:
        """Keep one transcript per (contig, strand, gene): the one with largest genomic span (Tiberius-style)."""
        buckets: dict = defaultdict(list)
        for tx in self.transcripts:
            if tx.start is None or tx.sequence_name is None or tx.strand is None:
                continue
            gkey = (tx.sequence_name, tx.strand, tx.gene_group_id or tx.id)
            buckets[gkey].append(tx)
        kept: List[Transcript] = []
        for _k, group in buckets.items():
            best = max(group, key=lambda t: t.end - t.start + 1)
            kept.append(best)
        self.transcripts = kept

    def get_full_chromosome_labels(
        self, seq_name: str, seq_len: int
    ) -> tuple[np.ndarray, np.ndarray]:
        """Per-strand label arrays for the full chromosome (0-based indexing). No array reversal."""
        labels_fwd = np.zeros(seq_len, dtype=np.int32)
        labels_rev = np.zeros(seq_len, dtype=np.int32)
        for tx in self.transcripts:
            if tx.sequence_name != seq_name or tx.start is None:
                continue
            # GFF 1-based inclusive -> 0-based half-open [lo, hi)
            lo, hi = tx.start - 1, tx.end
            lbl = tx.to_class_labels()
            if hi <= lo or len(lbl) != hi - lo:
                raise ValueError(
                    f"Transcript {tx.id} span/label mismatch on {seq_name}: "
                    f"lo={lo} hi={hi} len(lbl)={len(lbl)}"
                )
            # Clip when annotation extends past FASTA (assembly mismatch / partial contigs)
            eff_lo = max(lo, 0)
            eff_hi = min(hi, seq_len)
            if eff_lo >= eff_hi:
                continue
            a0 = eff_lo - lo
            a1 = a0 + (eff_hi - eff_lo)
            if tx.strand == "+":
                labels_fwd[eff_lo:eff_hi] = lbl[a0:a1]
            else:
                rev = lbl[::-1]
                labels_rev[eff_lo:eff_hi] = rev[a0:a1]
        return labels_fwd, labels_rev

    def get_region_labels(
        self, seq_name: str, reg_start: int, reg_end: int
    ) -> tuple:
        """Return (labels_plus, labels_minus) for region [reg_start, reg_end] (1-based inclusive).
        Each array has length (reg_end - reg_start + 1); index i = genomic position reg_start + i.
        Used for sanity-check plots: per-strand labels so overlapping +/- genes both show non-zero.
        """
        length = reg_end - reg_start + 1
        labels_plus = np.zeros(length, dtype=np.int32)
        labels_minus = np.zeros(length, dtype=np.int32)

        for tx in self.transcripts:
            if tx.sequence_name != seq_name or tx.start is None:
                continue
            # Overlap of transcript [tx.start, tx.end] with [reg_start, reg_end]
            ovl_start = max(tx.start, reg_start)
            ovl_end = min(tx.end, reg_end)
            if ovl_start > ovl_end:
                continue

            

            tx_labels = tx.to_class_labels()
            # Region indices (0-based) for overlap
            reg_lo = ovl_start - reg_start
            reg_hi = ovl_end - reg_start

            if tx.strand == "+":
                # + strand: transcript index = genomic position - tx.start
                tx_lo = ovl_start - tx.start
                tx_hi = ovl_end - tx.start
                labels_plus[reg_lo : reg_hi + 1] = tx_labels[tx_lo : tx_hi + 1]
            else:
                # - strand: Transcript stores 5' at index 0, 3' at end; so genomic g -> index tx.end - g
                tx_lo = tx.end - ovl_end
                tx_hi = tx.end - ovl_start
                labels_minus[reg_lo : reg_hi + 1] = tx_labels[tx_lo : tx_hi + 1][::-1]

        return labels_plus, labels_minus

    def get_merged_multilabel_labels(
        self, seq_name: str, seq_len: int
    ) -> np.ndarray:
        """Return direct transcript-wise multi-hot v4 labels.

        Do not build this tensor from :meth:`get_full_chromosome_labels`: those
        legacy per-strand arrays have one integer slot per base, so a later CDS
        overwrites an earlier same-strand CDS in an overlap.  Accumulating every
        transcript directly preserves combinations such as ``CDS+`` + ``START+``
        as well as opposite-strand overlaps.
        """
        y = np.zeros((seq_len, NUM_STATES_V4), dtype=np.float32)
        for tx in self.transcripts:
            if tx.sequence_name != seq_name or tx.start is None or tx.end is None:
                continue
            lo, hi = tx.start - 1, tx.end
            labels = tx.to_class_labels()
            if tx.strand == "-":
                # Transcript labels run in biological 5'→3' orientation; restore
                # increasing genomic-coordinate order before writing the tensor.
                labels = labels[::-1]
            if hi <= lo or len(labels) != hi - lo:
                raise ValueError(
                    f"Transcript {tx.id} span/label mismatch on {seq_name}: "
                    f"lo={lo} hi={hi} len(labels)={len(labels)}"
                )
            eff_lo = max(lo, 0)
            eff_hi = min(hi, seq_len)
            if eff_lo >= eff_hi:
                continue
            a0 = eff_lo - lo
            local = labels[a0 : a0 + (eff_hi - eff_lo)]
            positions = np.arange(eff_lo, eff_hi)
            if tx.strand == "+":
                for label, channel in ((1, 1), (2, 2), (3, 3), (4, 7), (5, 9)):
                    mask = local == label
                    y[positions[mask], channel] = 1.0
            else:
                for label, channel in ((1, 4), (2, 5), (3, 6), (4, 8), (5, 10)):
                    mask = local == label
                    y[positions[mask], channel] = 1.0

        # IGR means no feature on either strand; it must not coexist with a
        # coding or boundary label.
        y[:, 0] = (y[:, 1:].sum(axis=1) == 0).astype(np.float32)
        return y

    def get_merged_multilabel_labels_smorf_split_frames(
        self, seq_name: str, seq_len: int, *, max_nt: int = 300
    ) -> np.ndarray:
        """Multi-hot labels with independent small/long frame banks (17 channels).

        CDS body bases use small frame channels when parent span <= max_nt, else
        long frame channels. START/STOP are universal (not split by length).
        """
        y = np.zeros((seq_len, NUM_STATES_V4_SMORF_SPLIT), dtype=np.float32)
        for tx in self.transcripts:
            if tx.sequence_name != seq_name or tx.start is None or tx.end is None:
                continue
            span_nt = tx.end - tx.start + 1
            is_small = span_nt <= max_nt
            lo, hi = tx.start - 1, tx.end
            labels = tx.to_class_labels()
            if tx.strand == "-":
                labels = labels[::-1]
            if hi <= lo or len(labels) != hi - lo:
                raise ValueError(
                    f"Transcript {tx.id} span/label mismatch on {seq_name}: "
                    f"lo={lo} hi={hi} len(labels)={len(labels)}"
                )
            eff_lo = max(lo, 0)
            eff_hi = min(hi, seq_len)
            if eff_lo >= eff_hi:
                continue
            a0 = eff_lo - lo
            local = labels[a0 : a0 + (eff_hi - eff_lo)]
            positions = np.arange(eff_lo, eff_hi)
            if tx.strand == "+":
                frame_base = 1 if is_small else 7
                for label, channel in (
                    (1, frame_base),
                    (2, frame_base + 1),
                    (3, frame_base + 2),
                    (4, V4_SPLIT_CH_START_PLUS),
                    (5, V4_SPLIT_CH_STOP_PLUS),
                ):
                    mask = local == label
                    y[positions[mask], channel] = 1.0
            else:
                frame_base = 4 if is_small else 10
                for label, channel in (
                    (1, frame_base),
                    (2, frame_base + 1),
                    (3, frame_base + 2),
                    (4, V4_SPLIT_CH_START_MINUS),
                    (5, V4_SPLIT_CH_STOP_MINUS),
                ):
                    mask = local == label
                    y[positions[mask], channel] = 1.0

        y[:, 0] = (y[:, 1:].sum(axis=1) == 0).astype(np.float32)
        return y

    def get_smorf_binary_mask(
        self, seq_name: str, seq_len: int, *, max_nt: int = 300
    ) -> np.ndarray:
        """Per-base binary mask: 1 on bases in CDS with span length <= max_nt.

        Long-ORF coding bases, IGR, and boundary bases on long ORFs remain 0.
        START/STOP on short ORFs inherit the parent transcript length decision.
        """
        mask = np.zeros(seq_len, dtype=np.float32)
        for tx in self.transcripts:
            if tx.sequence_name != seq_name or tx.start is None or tx.end is None:
                continue
            span_nt = tx.end - tx.start + 1
            if span_nt > max_nt:
                continue
            lo, hi = tx.start - 1, tx.end
            eff_lo = max(lo, 0)
            eff_hi = min(hi, seq_len)
            if eff_lo >= eff_hi:
                continue
            mask[eff_lo:eff_hi] = 1.0
        return mask

    def get_orf_length_weight_mask(
        self,
        seq_name: str,
        seq_len: int,
        *,
        ref_nt: int = 300,
        min_weight: float = 1.0,
        max_weight: float = 5.0,
    ) -> np.ndarray:
        """Per-base loss weights from parent ORF length (Variant C).

        Coding bases inherit w = clip(ref_nt / span_nt, min_weight, max_weight).
        Shorter ORFs receive larger weights; IGR bases remain 1.0.
        """
        weights = np.ones(seq_len, dtype=np.float32)
        ref = float(ref_nt)
        lo_clip = float(min_weight)
        hi_clip = float(max_weight)
        for tx in self.transcripts:
            if tx.sequence_name != seq_name or tx.start is None or tx.end is None:
                continue
            span_nt = float(tx.end - tx.start + 1)
            tx_w = float(np.clip(ref / span_nt, lo_clip, hi_clip))
            lo, hi = tx.start - 1, tx.end
            eff_lo = max(lo, 0)
            eff_hi = min(hi, seq_len)
            if eff_lo >= eff_hi:
                continue
            weights[eff_lo:eff_hi] = tx_w
        return weights
